399	    private Xpb98Status mapToShipmentStatus(String statusText) {
400	        return switch (statusText) {
401	            case "배송완료" -> Xpb98Status.DELIVERED;
402	            case "배송출발" -> Xpb98Status.OUT_FOR_DELIVERY;
403	            default -> Xpb98Status.IN_TRANSIT;
404	        };
405	    }
