470	                throw new Xpb98Exception(
471	                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
472	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
473	                );
474	            }
475	
476	
477	            String statusText = rows.last().select("td").get(4).text().trim();
478	
479	            if (statusText.isEmpty()) {
480	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
481	                throw new Xpb98Exception(
482	                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
483	                        "배송 상태 정보를 찾을 수 없습니다."
484	                );
485	            }
486	
487	            return statusText;
488	
489	        } catch (IndexOutOfBoundsException e) {
490	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
491	            throw new Xpb98Exception(
492	                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
493	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
494	                    e
495	            );
496	        } catch (Exception e) {
497	            if (e instanceof Xpb98Exception) {
498	                throw (Xpb98Exception) e;
499	            }
500	
501	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
502	            throw new Xpb98Exception(
503	                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
504	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
505	                    e
506	            );
507	        }
508	    }
